class Solution {
    int n;
    vector<int> tree;

    void update(int i, int delta) {
        for (++i; i <= n; i += i & -i)
            tree[i] += delta;
    }

    int find_kth(int k) {
        int pos = 0;
        int log_n = 0;
        while ((1 << (log_n + 1)) <= n) log_n++;
        for (int i = log_n; i >= 0; i--) {
            int next_pos = pos + (1 << i);
            if (next_pos <= n && tree[next_pos] < k) {
                k -= tree[next_pos];
                pos = next_pos;
            }
        }
        return pos;
    }

public:
    vector<int> createTargetArray(vector<int>& nums, vector<int>& index) {
        n = nums.size();
        tree.assign(n + 1, 0);
        for (int i = 0; i < n; i++) {
            update(i, 1);
        }

        vector<int> target(n);
        for (int i = n - 1; i >= 0; i--) {
            int pos = find_kth(index[i] + 1);
            target[pos] = nums[i];
            update(pos, -1);
        }
        return target;
    }
};
